const CLRS = "6b2737-e08e45-f8f4a6-bdf7b7-3943b7"
  .split("-")
  .map((i) => "#" + i);

const MAX_WAVES = 99;
let waves;

function setup() {
  createCanvas(400, 400);
  pixelDensity(1);
  describe("animation of wave lines");
  frameRate(60);
  noStroke();
  background(0, 0, 8);

  waves = [];
}

function draw() {
  if (waves.length < MAX_WAVES) waves.push(new Wave());

  blendMode(BLEND);
  background(0, 0, 8);

  blendMode(ADD);
  for (let w of waves) {
    w.update();
    w.draw();
  }
  waves = waves.filter((w) => w.an < TWO_PI);

  push();
  blendMode(BLEND);
  stroke(0);
  fill(255);
  text("#minacoding 24/10 Screen saver", 0, 10);
  pop();
}

class Wave {
  constructor() {
    this.clr = lerpColor(color(CLRS[3]), color(CLRS[4]), random());
    this.sw = ~~random(1, 4);

    this.an = 0;
    this.da = random(0.0001, 0.01);

    this.x = ~~random(-width * 0.5, width);
    this.y = ~~random(height);
    this.w = ~~random(width * 0.25, width * 1.5);
    this.h = ~~random(4, height * 0.1);
  }

  update() {
    this.an += this.da;
  }

  draw() {
    let x = this.x + sin(this.an) * this.w,
      y = this.y,
      w = this.w,
      h = this.h;

		let clr = this.clr;
		const al = (1 - abs(PI - this.an) / PI) * 500
		clr.setAlpha(al);
    stroke(clr);
    strokeWeight(this.sw);

    for (let xd = 0; xd < w; xd += h) {
      const xx = x + xd;
      if (noise(xd, y) < 0.75) line(xx, y + h, xx + h, y);
      if (noise(xd, y) < 0.5) line(xx + h, y + h, xx + h, y);
    }
  }
}
